Filter(
    Table(
        {Value: "Home", Icon: mm, IconSelected: mm, Screen: Home1, RequiresAdmin: false},
        {Value: "Projects", Icon: projects, IconSelected: ImgHistorySelected, Screen: AI, RequiresAdmin: false},
        {Value: "LL by risk analysis", Icon: ImgBookingDisabled, IconSelected: ImgBookingSelected, Screen: Booking, RequiresAdmin: false},
        {Value: "Add LL by risk analysis", Icon: ImgCarDisabled, IconSelected: ImgCarSelected, Screen: Create, RequiresAdmin: true},
        {Value: "Processes", Icon: img1, IconSelected: ImgCreateSelected, Screen: proo, RequiresAdmin: false},
        {Value: "Fault catalog", Icon: ImgBookingDisabled, IconSelected: ImgBookingSelected, Screen: Bookingp, RequiresAdmin: false},
        {Value: "Add Lesson by process", Icon: addlesson, IconSelected: ImgCarSelected, Screen: Createp, RequiresAdmin: true}
    ),
    // La condition de filtrage :
    !RequiresAdmin || (RequiresAdmin && !IsBlank(CurrentUser) && IsAdminUser)
)

Filter(
    Table(
        {Value: "Home", Icon: mm, IconSelected: mm, Screen: Home1, RequiresAdmin: false},
        {Value: "Projects", Icon: projects, IconSelected: ImgHistorySelected, Screen: AI, RequiresAdmin: false},
        {Value: "LL by risk analysis", Icon: ImgBookingDisabled, IconSelected: ImgBookingSelected, Screen: Booking, RequiresAdmin: false},
        {Value: "Add LL by risk analysis", Icon: ImgCarDisabled, IconSelected: ImgCarSelected, Screen: Create, RequiresAdmin: true},
        {Value: "Processes", Icon: img1, IconSelected: ImgCreateSelected, Screen: proo, RequiresAdmin: false},
        {Value: "Fault catalog", Icon: ImgBookingDisabled, IconSelected: ImgBookingSelected, Screen: Bookingp, RequiresAdmin: false},
        {Value: "Add Lesson by process", Icon: addlesson, IconSelected: ImgCarSelected, Screen: Createp, RequiresAdmin: true}
    ),
    // La condition de filtrage :
    !RequiresAdmin || (RequiresAdmin && !IsBlank(CurrentUser) && IsAdminUser)
)

Filter(
    Table(
        {Value: "Home", Icon: mm, IconSelected: mm, Screen: Home1, RequiresAdmin: false},
        {Value: "Projects", Icon: projects, IconSelected: ImgHistorySelected, Screen: AI, RequiresAdmin: false},
        {Value: "LL by risk analysis", Icon: ImgBookingDisabled, IconSelected: ImgBookingSelected, Screen: Booking, RequiresAdmin: false},
        {Value: "Add LL by risk analysis", Icon: ImgCarDisabled, IconSelected: ImgCarSelected, Screen: Create, RequiresAdmin: true},
        {Value: "Processes", Icon: img1, IconSelected: ImgCreateSelected, Screen: proo, RequiresAdmin: false},
        {Value: "Fault catalog", Icon: ImgBookingDisabled, IconSelected: ImgBookingSelected, Screen: Bookingp, RequiresAdmin: false},
        {Value: "Add Lesson by process", Icon: addlesson, IconSelected: ImgCarSelected, Screen: Createp, RequiresAdmin: true}
    ),
    // La condition de filtrage :
    !RequiresAdmin || (RequiresAdmin && !IsBlank(CurrentUser) && IsAdminUser)
)

// Count the number of rows in the BookingListCollection
CountRows(
    Filter(
        BookingListCollection,
        Requestor.Email = User().Email // Filters by the currently logged-in user's email
    )
)

// Count the number of rows in the BookingListCollection where the BookingDate is Today 
CountRows(
    Filter(
        BookingListCollection,
        BookingStatus.Value = "Positive Lesson" && Requestor.Email = User().Email // Filters by the currently logged-in user's email


    )
)

// Count the number of rows in the BookingListCollection where the BookingStatus is "Cancelled" 
// and the Modified date is today
CountRows(
    Filter(
        BookingListCollection,
        BookingStatus.Value = "Cancelled" && Requestor.Email = User().Email // Filters by the currently logged-in user's email
        
        
    )
)

// Filter the BookingListCollection based in the logged in USer and various criteria and sort the results
SortByColumns(
    Filter(
        BookingListCollection,
        Requestor.Email = User().Email && 
        // Partial match for BookedCarID and BookedCarName using Txt_Filter_Dashboard_Search
        (IsBlank(Txt_Filter_MyBooking_Search.Text) ||
         // Check if BookedCarID starts with the search text
 StartsWith(
            Text(BookedCarID),
            Txt_Filter_MyBooking_Search.Text
        ) ||
         // Check if BookingPickupLocation starts with the search text
 StartsWith(
            Text(BookingPickupLocation),
            Txt_Filter_MyBooking_Search.Text
        ) ||
         // Check if BookingDropoffLocation starts with the search text
 StartsWith(
            Text(BookingDropoffLocation),
            Txt_Filter_MyBooking_Search.Text
        ) ||
         // Check if BookedCarName starts with the search text
 StartsWith(
            BookedCarName,
            Txt_Filter_MyBooking_Search.Text
        )),
        // Filter by BookingStatus (Choice column) using the collection
        (IsBlank(SelectedBookingStatus) ||
         // Check if the BookingStatus exists in the selected statuses
 CountRows(
            Filter(
                SelectedBookingStatus,
                Value = BookingStatus.Value
            )
        ) > 0),
        // Filter by BookingPurpose (Choice column) using the collection
        (IsBlank(SelectedBookingPurpose) ||
         // Check if the BookingPurpose exists in the selected purposes
 CountRows(
            Filter(
                SelectedBookingPurpose,
                Value = BookingPurpose
            )
        ) > 0),
        // Filter by date range
        (IsBlank(DatePickerFrom_Filter_MyBooking_DateRange.SelectedDate) || IsBlank(DatePickerTo_Filter_MyBooking_DateRange.SelectedDate) ||
         // Check if BookingDate is within the selected date range
 (BookingDate >= DatePickerFrom_Filter_MyBooking_DateRange.SelectedDate && BookingDate <= DatePickerTo_Filter_MyBooking_DateRange.SelectedDate))
    ),
    // Sort by the Created date in descending order to show the latest entries first
    "Created",
    SortOrder.Descending
)

If(
    Not(IsBlank(LookUp(SelectedBookingPurpose, Value = ThisItem.Value))),
    // Item is already in the collection, so remove it
    Remove(
        SelectedBookingPurpose,
        LookUp(SelectedBookingPurpose, Value = ThisItem.Value)
    ),
    // Item is not in the collection, so add it
    Collect(
        SelectedBookingPurpose,
        ThisItem
    )
)

If(
    Not(IsBlank(LookUp(SelectedBookingStatus, Value = ThisItem.Value))),
    // Item is already in the new collection, so remove it
    Remove(
        SelectedBookingStatus,
        LookUp(SelectedBookingStatus, Value = ThisItem.Value)
    );
    ,
    // Item is not in the new collection, so add it
    Collect(
        SelectedBookingStatus,
        ThisItem
    )
)

If(
    Not(IsBlank(LookUp(SelectedBookingStatus, Value = ThisItem.Value))),
    // Item is selected
    If(
        ThisItem.Value = "Booked",
        RGBA(48, 194, 27, 1), // Color for "Booked"
        If(
            ThisItem.Value = "Cancelled",
            RGBA(251, 25, 25, 1), // Color for "Cancelled"
            Parent.Fill // Default color if the status is neither "Booked" nor "Cancelled"
        )
    ),
    // Item is not selected
    RGBA(44, 44, 44, 1) // Default color when not selected
)

//Reset(TextInput2_2);
Reset(Txt_Filter_MyBooking_Search);
Reset(DatePickerFrom_Filter_MyBooking_DateRange);
Reset(DatePickerTo_Filter_MyBooking_DateRange);
// Populate SelectedBookingPurpose with default options from the BookingPurpose choice column
ClearCollect(
    SelectedBookingPurpose,
    Choices('Booking List'.BookingPurpose)
);

// Populate SelectedBookingStatus with default options from the BookingStatus choice column
ClearCollect(
    SelectedBookingStatus,
    Choices('Booking List'.BookingStatus)
);

UpdateContext({ShowLoader:true});
If(
    Not(IsBlank(VarRecord)),  // Ensure VarRecord has a value
    // First, patch the BookingStatus to "Cancelled"
    Patch(
        'Booking List',  
        LookUp('Booking List', ID = VarRecord.ID),  // Find the matching item by ID in SharePoint list
        {
            BookingStatus: { Value: "Cancelled" }
        }
    );
    
    // Send email notification to the Requestor and BookingOccupants
    Office365Outlook.SendEmailV2(
        VarRecord.Requestor.Email,  // Email address of the Requestor (assuming it's a Person field)
        "Booking Cancellation Notification",  // Subject of the email
        "Dear " & VarRecord.Requestor.DisplayName & "," & 
        "<br><br>Your booking for the car with ID " & VarRecord.BookedCarID & " has been cancelled." & 
        "<br>Details:" &
        "<br>Booking Purpose: " & VarRecord.BookingPurpose.Value & 
        "<br>Booking Date: " & Text(VarRecord.BookingDate, "[$-en-US]dd/mm/yyyy") & 
        "<br><br>Thank you.",  // Body of the email (HTML formatted),
        {
            To: Concat(VarRecord.BookingOccupants, Email & ";")  // Send to multiple occupants, assuming BookingOccupants is a Person/Group column
        }
    );
    
    Notify("Booking has been cancelled, and an email notification has been sent.", NotificationType.Success),
    
    Notify("No record selected to cancel.", NotificationType.Error)  // Handle the case where VarRecord is blank
);

ClearCollect(BookingListCollection,'Booking List');
UpdateContext({AllBookingPopup:false});
UpdateContext({ShowLoader:false});
UpdateContext({ConfirmationPopup:true})
